{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/story-tabs.json
    A story in steps (years or slides). Axes: layout (years: a row of year tabs over the panel of the active year with its badge, step, title, text and tag; carousel: the heading beside a picture with previous and next arrows and one dot per step), tone. Choosing a step emits `select`.
    Props (p): id, title, lead, badge, steps, empty, active, labels, layout, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_badge = ($p['badge'] ?? '')}
{var $v_steps = ($p['steps'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_active = ($p['active'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'years')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{if og_t(og_eq(og_len($v_steps), 0))}
  {capture $c_1}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'milestone', 'title' => $v_empty]])|noescape}
  {/capture}
  {=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'heading' => ['badge' => $v_badge], 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_1)])|noescape}
{elseif og_t(og_eq($v_layout, 'years'))}
  {capture $c_6}
    {capture $c_5}
      {foreach og_l($v_steps) as $v_s}
        {capture $c_4}
          {capture $c_2}
            {=og_text(og_get($v_s, ['date']))}
          {/capture}
          {=og_include('compose/Inline.latte', ['class' => 'text-sm font-semibold', 'children' => (string) $c_2])|noescape}
          {capture $c_3}
            {=og_text(og_get($v_s, ['tag']))}
          {/capture}
          {=og_include('compose/Inline.latte', ['class' => 'text-xs', 'children' => (string) $c_3])|noescape}
        {/capture}
        {=og_include('compose/Button.latte', ['variant' => og_s((og_t(og_eq(og_get($v_s, ['id']), $v_active)) ? 'default' : 'outline')), 'size' => 'lg', 'type' => 'button', 'class' => 'h-auto flex-col items-start gap-0 py-2 text-start', 'attrs' => og_attrs(['data-active', (og_t(og_eq(og_get($v_s, ['id']), $v_active)) ? 'true' : 'false')]), 'children' => (string) $c_4])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/Box.latte', ['class' => 'grid grid-cols-2 gap-2 sm:grid-cols-4', 'attrs' => og_attrs(['data-slot', 'story-tabs']), 'children' => (string) $c_5])|noescape}
    {foreach og_l($v_steps) as $v_s}
      {var $v_i = $iterator->counter0}
      {if og_t(og_eq(og_get($v_s, ['id']), $v_active))}
        {=og_include('blocks/story-panel.latte', ['p' => ['s' => $v_s, 'index' => $v_i, 'total' => og_len($v_steps), 'labels' => $v_labels]])|noescape}
      {/if}
    {/foreach}
  {/capture}
  {=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'heading' => ['badge' => $v_badge], 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_6)])|noescape}
{else}
  {capture $f_7}
    {capture $c_11}
      {=og_include('blocks/media-frame.latte', ['p' => ['alt' => $v_title, 'ratio' => '4/3']])|noescape}
      {capture $c_10}
        {capture $c_8}
          {=og_include('icons/LucideIcon.latte', ['name' => 'chevron-left', 'size' => 16])|noescape}
        {/capture}
        {=og_include('compose/Button.latte', ['variant' => 'outline', 'size' => 'sm', 'layout' => 'icon', 'type' => 'button', 'ariaLabel' => og_s(og_get($v_labels, ['previous'])), 'children' => (string) $c_8])|noescape}
        {=og_include('blocks/story-dots.latte', ['p' => ['steps' => $v_steps, 'active' => $v_active]])|noescape}
        {capture $c_9}
          {=og_include('icons/LucideIcon.latte', ['name' => 'chevron-right', 'size' => 16])|noescape}
        {/capture}
        {=og_include('compose/Button.latte', ['variant' => 'outline', 'size' => 'sm', 'layout' => 'icon', 'type' => 'button', 'ariaLabel' => og_s(og_get($v_labels, ['next'])), 'children' => (string) $c_9])|noescape}
      {/capture}
      {=og_include('compose/Group.latte', ['gap' => '4', 'align' => 'center', 'justify' => 'between', 'children' => (string) $c_10])|noescape}
    {/capture}
    {=og_include('compose/Stack.latte', ['gap' => '4', 'align' => 'stretch', 'children' => (string) $c_11])|noescape}
  {/capture}
  {=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'heading' => ['badge' => $v_badge], 'tone' => $v_tone, 'layout' => 'split', 'media' => ['show' => true], 'landmarkLabel' => $v_landmarkLabel, 'aside' => og_markup($f_7)]])|noescape}
{/if}
